CREATE TABLE payroll_configurations (id uuid PRIMARY KEY DEFAULT uuidv7(), organization_id uuid NOT NULL UNIQUE REFERENCES organizations(id), configuration jsonb NOT NULL CHECK(jsonb_typeof(configuration)='object'), revision integer NOT NULL DEFAULT 1 CHECK(revision>0), updated_by uuid REFERENCES auth_users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT uuidv7(), organization_id uuid REFERENCES organizations(id), user_id uuid REFERENCES auth_users(id), action text NOT NULL CHECK(action IN ('CREATE','UPDATE','ARCHIVE','ACTIVATE','DEACTIVATE','LOGIN','LOGOUT','CONFIG_CHANGE','ROLE_CHANGE')), entity_type text NOT NULL, entity_id uuid, description text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(metadata)='object'), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_filter_idx ON audit_events(organization_id,created_at DESC);
REVOKE UPDATE,DELETE,TRUNCATE ON audit_events FROM hexpayroll_app;
CREATE TABLE sync_nodes (id uuid PRIMARY KEY DEFAULT uuidv7(), organization_id uuid NOT NULL REFERENCES organizations(id), device_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz);
CREATE TABLE sync_outbox (id uuid PRIMARY KEY DEFAULT uuidv7(), organization_id uuid NOT NULL REFERENCES organizations(id), entity_type text NOT NULL, entity_id uuid NOT NULL, operation text NOT NULL CHECK(operation IN ('CREATE','UPDATE','ARCHIVE')), revision integer NOT NULL CHECK(revision>0), payload_version integer NOT NULL DEFAULT 1, payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object' AND octet_length(payload::text)<=262144), created_at timestamptz NOT NULL DEFAULT now(), attempt_count integer NOT NULL DEFAULT 0 CHECK(attempt_count>=0), last_attempt_at timestamptz, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','synced','failed')), error text, UNIQUE(entity_type,entity_id,revision));
CREATE INDEX outbox_pending_idx ON sync_outbox(organization_id,status,created_at);
